function StudentCard({ name, studyHours, predictedPass }) {
  const status = predictedPass ? "On track to pass" : "At risk \u2014 needs more study time";
  const badge = predictedPass ? "\u2705" : "\u26A0\uFE0F";
  return `${badge} ${name}: ${studyHours}h studied \u2014 ${status}`;
}

// Using the EXACT predictions from the AI Engineer lesson --
// Farid (2.5h, predicted fail) and Chen-equivalent (8h, predicted pass)
const students = [
  { name: "Farid", studyHours: 2.5, predictedPass: false },
  { name: "Chen", studyHours: 8, predictedPass: true },
];

for (const s of students) {
  console.log(StudentCard(s));
}
